import math

# تهيئة لوحة اللعبة
board = [" " for _ in range(9)]


def print_board():
    row1 = f" {board[0]} | {board[1]} | {board[2]} "
    row2 = f" {board[3]} | {board[4]} | {board[5]} "
    row3 = f" {board[6]} | {board[7]} | {board[8]} "
    print(row1)
    print("-" * 11)
    print(row2)
    print("-" * 11)
    print(row3)


def check_winner(b, player):
    win_conds = [
        (0, 1, 2), (3, 4, 5), (6, 7, 8), # الصفوف
        (0, 3, 6), (1, 4, 7), (2, 5, 8), # الأعمدة
        (0, 4, 8), (2, 4, 6)             # الأقطار
    ]
    for cond in win_conds:
        if b[cond[0]] == b[cond[1]] == b[cond[2]] == player:
            return True
    return False


def is_full(b):
    return " " not in b


# خوارزمية مينيماكس لذكاء اصطناعي لا يُقهر
def minimax(b, depth, is_maximizing):
    if check_winner(b, "O"): 
        return 1
    if check_winner(b, "X"): 
        return -1
    if is_full(b): 
        return 0


    if is_maximizing:
        max_eval = -math.inf
        for i in range(9):
            if b[i] == " ":
                b[i] = "O"
                eval = minimax(b, depth + 1, False)
                b[i] = " "
                max_eval = max(max_eval, eval)
        return max_eval
    else:
        min_eval = math.inf
        for i in range(9):
            if b[i] == " ":
                b[i] = "X"
                eval = minimax(b, depth + 1, True)
                b[i] = " "
                min_eval = min(min_eval, eval)
        return min_eval


def ai_move():
    best_score = -math.inf
    move = 0
    for i in range(9):
        if board[i] == " ":
            board[i] = "O"
            score = minimax(board, 0, False)
            board[i] = " "
            if score > best_score:
                best_score = score
                move = i
    board[move] = "O"


def play_game():
    print("مرحباً بك في لعبة تيك-تاك-toe! أنت 'X' والذكاء الاصطناعي 'O'.")
    print_board()


    while True:
        try:
            choice = int(input("أدخل خطوتك (من 0 إلى 8): "))
            if board[choice] == " ":
                board[choice] = "X"
            else:
                print("هذا المكان محجوز! اختر مكاناً آخر.")
                continue
        except (ValueError, IndexError):
            print("إدخال غير صالح. أدخل رقماً بين 0 و 8.")
            continue


        if check_winner(board, "X"):
            print_board()
            print("تهانينا، لقد فزت!")
            break
        if is_full(board):
            print_board()
            print("تعادل!")
            break


        print("الذكاء الاصطناعي يفكر...")
        ai_move()


        if check_winner(board, "O"):
            print_board()
            print("فاز الذكاء الاصطناعي! حظاً أوفر في المرة القادمة.")
            break
        if is_full(board):
            print_board()
            print("تعادل!")
            break


        print_board()


if __name__ == "__main__":
    play_game()

